/** Get MLA profile by constituency number */
export function getKLMLAProfile(acNo: number): MLAProfile | undefined {
  return KL_MLA_PROFILES.find((p) => p.acNo === acNo);
}

/** Get all MLA profiles */
export function getAllKLMLAs(): MLAProfile[] {
  return KL_MLA_PROFILES;
}
